fn close_step(&mut self,parent:&mut impl SpaceMember,registry:&mut ChildMemberRegistry<M>,graph:&mut store::CompositionGraph,live:&ChildContentView,grant:RetainedCloneGrant)->Result<semio_framework_value::retained_clone::RetainedCloneStep,Fault>{
    use semio_framework_value::retained_clone::{RetainedCloneProgress,RetainedCloneStep};
    if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}
    let demand=self.retirement_demands(grant.maximum_copy_bytes).map_err(|error|plugin_sdk_fault(error.to_string()))?;
    if !mounted_child_group_receipt::mounted_retirement_grant_funds(demand, grant){return Ok(RetainedCloneStep::Progress(Default::default()));}
    let bytes=demand.release_bytes;
    let child_grant=RetainedCloneGrant{maximum_items:1,maximum_depth:grant.maximum_depth-1,..grant};
    self.closing=true;
    if self.output.is_some(){return Ok(self.receipts.as_mut().and_then(|receipts|receipts.final_receipt_mut()).expect("transferred output retains its exact empty receipt owner").retain_output(&mut self.output,child_grant));}
    if let Some(record)=self.record.as_mut(){if self.record_close_field==8{self.record.take();}else if PagedCommandLog::record_close_one(record,self.record_close_field){self.record_close_field+=1;}return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
    if let Some(replay)=self.displaced_shell_redo.last_mut(){if replay.redo.action_id.capacity()!=0{drop(std::mem::take(&mut replay.redo.action_id));}else if let Some(value)=replay.redo.args.as_mut(){if matches!(value,DslValue::Null){replay.redo.args.take();}else{PagedCommandLog::value_close_one(value);}}else{self.displaced_shell_redo.pop();}return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
    if self.displaced_shell_redo.capacity()!=0{drop(std::mem::take(&mut*self.displaced_shell_redo));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
    if let Some(append)=self.append.as_mut(){let step=append.close_step(child_grant);self.append=None;return Ok(step);}
    if let Some(command)=self.command.as_mut(){let step=command.close_step(child_grant);if command.terminal_is_empty(){self.command=None;}return Ok(step);}
    if let Some(receipts)=self.receipts.as_mut(){if !receipts.terminal_is_empty(){return receipts.close_step(RetainedCloneGrant { maximum_depth: grant.maximum_depth - 2, ..child_grant }).map_err(|error|plugin_sdk_fault(error.to_string()));}drop(self.receipts.take());return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
    if let Some(group)=self.publication.as_mut(){let step=group.close_step(parent,registry,graph,live,child_grant)?;if group.terminal_is_empty(){self.publication.take();}return Ok(step);}
    if let Some(context)=self.context.as_mut(){
        let progress=match context.close_step(child_grant){
            semio_framework_job::InteractiveJobCloseStep::Pending{progress}=>progress,
            semio_framework_job::InteractiveJobCloseStep::Blocked=>return Err(Fault::new(FaultOrigin::Framework,FaultCode::new("mounted-publication.retirement-blocked"),"original step context ledger remains held by its live borrower")),
            semio_framework_job::InteractiveJobCloseStep::Complete{progress}=>{self.context=None;progress},
            semio_framework_job::InteractiveJobCloseStep::Refused(kind)=>return Err(plugin_sdk_fault(format!("original step context retirement refused: {kind:?}"))),
        };
        let step=RetainedCloneStep::Progress(progress);
        semio_framework_value::admit_retained_clone_close(step,child_grant).map_err(|error|plugin_sdk_fault(error.to_string()))?;
        return Ok(step);
    }
    if let Some(batch)=self.parent_batch.as_mut(){let step=batch.close_granted(child_grant).map_err(|error|plugin_sdk_fault(error.to_string()))?;if batch.terminal_is_empty(){self.parent_batch.take();}return Ok(step);}
    if self.group_id.is_some(){drop(self.group_id.take());return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
    if !self.identity.terminal_is_empty(){return Ok(self.identity.close_granted(child_grant));}
    if !self.parent_issuer_closed{let step=self.parent_issuer.close_step(child_grant);self.parent_issuer_closed=true;return Ok(step);}
    Ok(RetainedCloneStep::Complete(Default::default()))
}
